CREATE TABLE en1990_document(id INTEGER PRIMARY KEY, annex TEXT NOT NULL CHECK(annex IN ('En','De')), project_id TEXT NOT NULL, structure_kind TEXT NOT NULL, altitude_m REAL, consequence_class INTEGER NOT NULL CHECK(consequence_class>=0 AND consequence_class<=255), reliability_class INTEGER NOT NULL CHECK(reliability_class>=0 AND reliability_class<=255), design_working_life_category INTEGER NOT NULL CHECK(design_working_life_category>=0 AND design_working_life_category<=255), design_working_life_years REAL, reference_period_years REAL, supervision_level TEXT NOT NULL, inspection_level TEXT NOT NULL, k_fi_declared REAL, beta_computed REAL, altitude_m_ieee754_bits INTEGER NOT NULL, altitude_m_ieee754_class TEXT NOT NULL, design_working_life_years_ieee754_bits INTEGER NOT NULL, design_working_life_years_ieee754_class TEXT NOT NULL, reference_period_years_ieee754_bits INTEGER NOT NULL, reference_period_years_ieee754_class TEXT NOT NULL, k_fi_declared_ieee754_bits INTEGER NOT NULL, k_fi_declared_ieee754_class TEXT NOT NULL, beta_computed_ieee754_bits INTEGER NOT NULL, beta_computed_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_action(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), kind TEXT NOT NULL CHECK(kind IN ('permanent','variable','accidental','seismic')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL);
CREATE TABLE en1990_permanent_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), kind TEXT NOT NULL, gk REAL, gk_ieee754_bits INTEGER NOT NULL, gk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_variable_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), category TEXT NOT NULL, qk REAL, qk_ieee754_bits INTEGER NOT NULL, qk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_accidental_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), ad REAL, ad_ieee754_bits INTEGER NOT NULL, ad_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_seismic_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), a_ek REAL, importance_class TEXT NOT NULL CHECK(importance_class IN ('I','II','III','IV')), a_ek_ieee754_bits INTEGER NOT NULL, a_ek_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_member(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, label_en TEXT NOT NULL, label_de TEXT NOT NULL, rd_str REAL, rd_geo REAL, rd_equ_stab REAL, rd_equ_destab REAL, rd_fat REAL, span REAL, deflection_w REAL, deflection_limit_ratio REAL, vibration_frequency REAL, vibration_frequency_min REAL, rd_str_ieee754_bits INTEGER NOT NULL, rd_str_ieee754_class TEXT NOT NULL, rd_geo_ieee754_bits INTEGER NOT NULL, rd_geo_ieee754_class TEXT NOT NULL, rd_equ_stab_ieee754_bits INTEGER NOT NULL, rd_equ_stab_ieee754_class TEXT NOT NULL, rd_equ_destab_ieee754_bits INTEGER NOT NULL, rd_equ_destab_ieee754_class TEXT NOT NULL, rd_fat_ieee754_bits INTEGER NOT NULL, rd_fat_ieee754_class TEXT NOT NULL, span_ieee754_bits INTEGER NOT NULL, span_ieee754_class TEXT NOT NULL, deflection_w_ieee754_bits INTEGER NOT NULL, deflection_w_ieee754_class TEXT NOT NULL, deflection_limit_ratio_ieee754_bits INTEGER NOT NULL, deflection_limit_ratio_ieee754_class TEXT NOT NULL, vibration_frequency_ieee754_bits INTEGER NOT NULL, vibration_frequency_ieee754_class TEXT NOT NULL, vibration_frequency_min_ieee754_bits INTEGER NOT NULL, vibration_frequency_min_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_bridge_sls(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, member_reference TEXT NOT NULL, resolved_member_id INTEGER REFERENCES en1990_member(id), deck_acceleration REAL, deck_acceleration_limit REAL, deck_twist REAL, deck_twist_limit REAL, bridge_deflection REAL, bridge_deflection_limit REAL, deck_acceleration_ieee754_bits INTEGER NOT NULL, deck_acceleration_ieee754_class TEXT NOT NULL, deck_acceleration_limit_ieee754_bits INTEGER NOT NULL, deck_acceleration_limit_ieee754_class TEXT NOT NULL, deck_twist_ieee754_bits INTEGER NOT NULL, deck_twist_ieee754_class TEXT NOT NULL, deck_twist_limit_ieee754_bits INTEGER NOT NULL, deck_twist_limit_ieee754_class TEXT NOT NULL, bridge_deflection_ieee754_bits INTEGER NOT NULL, bridge_deflection_ieee754_class TEXT NOT NULL, bridge_deflection_limit_ieee754_bits INTEGER NOT NULL, bridge_deflection_limit_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_effect(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), member_reference TEXT NOT NULL, action_reference TEXT NOT NULL, resolved_member_id INTEGER REFERENCES en1990_member(id), resolved_action_id INTEGER REFERENCES en1990_action(id), influence REAL, influence_ieee754_bits INTEGER NOT NULL, influence_ieee754_class TEXT NOT NULL);
